:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #24342f;
  background: #f4f0e8;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at top, #fffdf8 0, #f4f0e8 72%);
}

.card {
  width: min(100%, 520px);
  padding: clamp(24px, 6vw, 40px);
  border: 1px solid #e3ddd0;
  border-radius: 24px;
  background: #fffdf8;
  box-shadow: 0 18px 55px #24342f14;
}

.header { margin-bottom: 28px; }
.eyebrow {
  margin: 0 0 8px;
  color: #73836f;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
}
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.5rem); line-height: 1.1; letter-spacing: -.04em; }
.intro { margin: 10px 0 0; color: #697771; line-height: 1.5; }

.board { width: min(100%, 400px); margin: 0 auto; }
.grid-wrap { display: grid; grid-template-columns: minmax(0, 1fr) 58px; gap: 10px; }
.grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 10px;
  border-radius: 18px;
  background: #e9eee7;
}
.cell {
  width: 100%;
  min-width: 0;
  aspect-ratio: 1;
  padding: 0;
  border: 1px solid #d5ded2;
  border-radius: 12px;
  background: #fffdf8;
  color: #24342f;
  font: inherit;
  font-size: clamp(1.1rem, 5vw, 1.5rem);
  font-weight: 650;
  text-align: center;
  transition: border-color .15s, background .15s, box-shadow .15s;
  appearance: textfield;
}
.cell::-webkit-inner-spin-button, .cell::-webkit-outer-spin-button { appearance: none; margin: 0; }
.cell:hover { border-color: #91a58e; background: #fbfcf8; }
.cell:focus-visible { outline: 3px solid #d59b57; outline-offset: 2px; z-index: 1; }
.sum-column, .column-sums { display: grid; gap: 8px; }
.sum-cell {
  display: grid;
  place-items: center;
  min-width: 0;
  border-radius: 12px;
  background: #f4f0e8;
  color: #58675e;
  font-size: .9rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.sum-cell::before { content: ""; }
.sum-cell.leading { background: #f5e4ca; color: #774d20; box-shadow: inset 0 0 0 1px #e9c995; }
.column-sums { grid-template-columns: repeat(4, minmax(0, 1fr)); margin: 10px 68px 0 10px; }
.column-sums .sum-cell { min-height: 38px; }
.summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 24px;
  padding: 16px 18px;
  border-radius: 14px;
  background: #24342f;
  color: #fffdf8;
  font-weight: 600;
}
.summary output { color: #f3c27c; font-size: 1.5rem; font-weight: 750; font-variant-numeric: tabular-nums; }
.randomize {
  width: 100%;
  min-height: 52px;
  margin-top: 14px;
  border: 0;
  border-radius: 14px;
  background: #d59b57;
  color: #24342f;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: background .15s, transform .1s, box-shadow .15s;
}
.randomize:hover { background: #e0aa68; }
.randomize:focus-visible { outline: 3px solid #24342f; outline-offset: 3px; }
.randomize:active { transform: translateY(1px); background: #c78c49; }
.hint { margin: 14px 0 0; color: #77837b; font-size: .875rem; text-align: center; }

@media (max-width: 400px) {
  .grid-wrap { grid-template-columns: minmax(0, 1fr) 50px; gap: 7px; }
  .grid { gap: 6px; padding: 8px; }
  .column-sums { gap: 6px; margin: 8px 57px 0 8px; }
  .sum-cell { border-radius: 9px; font-size: .8rem; }
}

const grid = document.getElementById('number-grid');
const rowSums = document.getElementById('row-sums');
const columnSums = document.getElementById('column-sums');
const grandTotal = document.getElementById('grand-total');
const randomizeButton = document.getElementById('randomize');
const cells = [];
const rowOutputs = [];
const columnOutputs = [];

for (let row = 0; row < 4; row += 1) {
  for (let column = 0; column < 4; column += 1) {
    const input = document.createElement('input');
    input.className = 'cell';
    input.type = 'number';
    input.min = '0';
    input.max = '999';
    input.step = '1';
    input.value = '0';
    input.setAttribute('aria-label', `Row ${row + 1}, column ${column + 1}`);
    input.addEventListener('input', updateTotals);
    grid.append(input);
    cells.push(input);
  }

  const output = document.createElement('output');
  output.className = 'sum-cell';
  output.setAttribute('aria-label', `Row ${row + 1} sum`);
  rowSums.append(output);
  rowOutputs.push(output);
}

for (let column = 0; column < 4; column += 1) {
  const output = document.createElement('output');
  output.className = 'sum-cell';
  output.setAttribute('aria-label', `Column ${column + 1} sum`);
  columnSums.append(output);
  columnOutputs.push(output);
}

function numericValue(input) {
  const value = Number(input.value);
  return Number.isFinite(value) ? value : 0;
}

function updateTotals() {
  const values = cells.map(numericValue);
  const sums = [0, 0, 0, 0];

  for (let row = 0; row < 4; row += 1) {
    const sum = values.slice(row * 4, row * 4 + 4).reduce((total, value) => total + value, 0);
    rowOutputs[row].value = String(sum);
    sums[row] = sum;
  }

  const largest = Math.max(...sums);
  rowOutputs.forEach((output, index) => {
    output.classList.toggle('leading', sums[index] === largest);
  });

  for (let column = 0; column < 4; column += 1) {
    let sum = 0;
    for (let row = 0; row < 4; row += 1) sum += values[row * 4 + column];
    columnOutputs[column].value = String(sum);
  }

  grandTotal.value = String(values.reduce((total, value) => total + value, 0));
}

randomizeButton.addEventListener('click', () => {
  cells.forEach((input) => {
    input.value = String(Math.floor(Math.random() * 9) + 1);
  });
  updateTotals();
});

updateTotals();
